import {PACK_COST,PACK_WH,PACK_KG,carriedPack,storedPackMass} from './battery-packs.js';
export function renderBatteryPacks(s,r,{enabled=true,near=false,stopped=false}={}){
 const pack=carriedPack(s,r),live=r.task&&['RUNNING','PAUSED'].includes(r.task.state),docked=r.system.mode==='DOCK',canLoad=['engineer','cargo'].includes(r.type),button=(id,label,disabled=false)=>`<button data-pack-op="${id}" ${!enabled||disabled?'disabled':''}>${label}</button>`;
 return `<section class="fleetTask" aria-label="Harvest battery packs"><div class="sectionHeading"><span>TRAILER / REMOVABLE PACKS</span><b>${s.batteryPacks.packs.length} / 8 PACKS</b></div><h3>Bring the charge home</h3><p>Assemble an empty ${PACK_WH} Wh pack (${PACK_KG} kg), load Utility, then assign Harvest &amp; deliver. It tops up its flight battery, charges the pack to 90%, releases the wire and returns to the trailer. Cargo can carry a pack; Utility has the line coupler.</p><p>${pack?`${pack.id.toUpperCase()} aboard · ${pack.chargeWh.toFixed(1)} / ${PACK_WH} Wh`:'No pack on selected aircraft'} · Trailer reserve ${(s.trailer/40*100).toFixed(0)}%</p><div class="taskActions">${button('build','ASSEMBLE EMPTY PACK',!near||!stopped||s.batteryPacks.serial>=8||Object.entries(PACK_COST).some(([k,n])=>(s.inv[k]||0)<n))}${button('load','LOAD LOWEST-CHARGE PACK',!near||!stopped||!docked||live||!!pack||!canLoad||!s.batteryPacks.packs.some(p=>p.owner==='trailer'))}${button('harvest','HARVEST & DELIVER',r.type!=='engineer'||!s.engineerBuilt||s.leg!==1||!pack||live)}${button('unload','UNLOAD CARRIED PACK',!pack||!near||!stopped||!docked||live)}${button('drain','STORED PACKS → RESERVE',!near||!stopped||s.trailer>=40||!s.batteryPacks.packs.some(p=>p.owner==='trailer'&&p.chargeWh>0))}</div><p class="hint">Assembly: 1 cell + 2 wire + 1 electronics + 1 rubber. Stop within 8 m of the trailer to manage packs. Stored packs occupy ${storedPackMass(s).toFixed(1)} kg of cargo space. Excess charge stays in the pack when the reserve is full. Recall or failure keeps the pack on its aircraft.</p><details><summary>Pack manifest</summary>${s.batteryPacks.packs.map(p=>`<p>${p.id.toUpperCase()} · ${p.chargeWh.toFixed(1)} / ${p.capacityWh} Wh · ${p.owner==='trailer'?'TRAILER':p.owner.replace('aircraft-','').toUpperCase()}</p>`).join('')||'<p>No packs assembled.</p>'}</details></section>`;
}
